import sys

def minimumSum(S):
    n = len(S)
    S = list(S)
    for i in range(n // 2):
        if S[i] == '?' and S[n - i - 1] != '?':
            S[i] = S[n - i - 1]
        elif S[n - i - 1] == '?' and S[i] != '?':
            S[n - i - 1] = S[i]
        elif S[i] == '?' and S[n - i - 1] == '?':
            S[i] = S[n - i - 1] = 'a'
        if S[i] != S[n - i - 1]:
            return -1
    result = 0
    for i in range(n - 1):
        result += abs(ord(S[i]) - ord(S[i + 1]))
    return result

input = sys.stdin.read().strip()
print(minimumSum(input))
